    /// <summary>
    /// A list of container definitions in JSON format that describe the containers that make up your daemon task. (structure) A container definition for a daemon task. Daemon container defi- nitions describe the containers that run as part of a daemon task on container instances managed by capacity providers. name -&gt; (string) The name of the container. Up to 255 letters (uppercase and lowercase), numbers, underscores, and hyphens are allowed. image -&gt; (string) [required] The image used to start the container. This string is passed directly to the Docker daemon. Images in the Docker Hub reg- istry are available by default. Other repositories are speci- fied with either `` repository-url /image :tag `` or `` repository-url /image @*digest* `` . memory -&gt; (integer) The amount (in MiB) of memory to present to the container. If the container attempts to exceed the memory specified here, the container is killed. memoryReservation -&gt; (integer) The soft limit (in MiB) of memory to reserve for the con- tainer. repositoryCredentials -&gt; (structure) The private repository authentication credentials to use. credentialsParameter -&gt; (string) [required] The Amazon Resource Name (ARN) of the secret containing the private repository credentials. NOTE: When you use the Amazon ECS API, CLI, or Amazon Web Services SDK, if the secret exists in the same Region as the task that you're launching then you can use ei- ther the full ARN or the name of the secret. When you use the Amazon Web Services Management Console, you must specify the full ARN of the secret. healthCheck -&gt; (structure) The container health check command and associated configura- tion parameters for the container. command -&gt; (list) [required] A string array representing the command that the con- tainer runs to determine if it is healthy. The string ar- ray must start with CMD to run the command arguments di- rectly, or CMD-SHELL to run the command with the con- tainer's default shell. When you use the Amazon Web Services Management Console JSON panel, the Command Line Interface, or the APIs, en- close the list of commands in double quotes and brackets. [ "CMD-SHELL", "curl -f http://localhost/ || exit 1" ] You don't include the double quotes and brackets when you use the Amazon Web Services Management Console. CMD-SHELL, curl -f http://localhost/ || exit 1 An exit code of 0 indicates success, and non-zero exit code indicates failure. For more information, see HealthCheck in the docker container create command. (string) interval -&gt; (integer) The time period in seconds between each health check exe- cution. You may specify between 5 and 300 seconds. The default value is 30 seconds. This value applies only when you specify a command . timeout -&gt; (integer) The time period in seconds to wait for a health check to succeed before it is considered a failure. You may spec- ify between 2 and 60 seconds. The default value is 5. This value applies only when you specify a command . retries -&gt; (integer) The number of times to retry a failed health check before the container is considered unhealthy. You may specify between 1 and 10 retries. The default value is 3. This value applies only when you specify a command . startPeriod -&gt; (integer) The optional grace period to provide containers time to bootstrap before failed health checks count towards the maximum number of retries. You can specify between 0 and 300 seconds. By default, the startPeriod is off. This value applies only when you specify a command . NOTE: If a health check succeeds within the startPeriod , then the container is considered healthy and any sub- sequent failures count toward the maximum number of retries. cpu -&gt; (integer) The number of cpu units reserved for the container. essential -&gt; (boolean) If the essential parameter of a container is marked as true , and that container fails or stops for any reason, all other containers that are part of the task are stopped. entryPoint -&gt; (list) The entry point that's passed to the container. (string) command -&gt; (list) The command that's passed to the container. (string) workingDirectory -&gt; (string) The working directory to run commands inside the container in. environmentFiles -&gt; (list) A list of files containing the environment variables to pass to a container. (structure) A list of files containing the environment variables to pass to a container. You can specify up to ten environ- ment files. The file must have a .env file extension. Each line in an environment file should contain an envi- ronment variable in VARIABLE=VALUE format. Lines begin- ning with # are treated as comments and are ignored. If there are environment variables specified using the environment parameter in a container definition, they take precedence over the variables contained within an environment file. If multiple environment files are spec- ified that contain the same variable, they're processed from the top down. We recommend that you use unique vari- able names. For more information, see Use a file to pass environment variables to a container in the Amazon Elas- tic Container Service Developer Guide . Environment variable files are objects in Amazon S3 and all Amazon S3 security considerations apply. You must use the following platforms for the Fargate launch type: o Linux platform version 1.4.0 or later. o Windows platform version 1.0.0 or later. Consider the following when using the Fargate launch type: o The file is handled like a native Docker env-file. o There is no support for shell escape handling. o The container entry point interperts the VARIABLE val- ues. value -&gt; (string) [required] The Amazon Resource Name (ARN) of the Amazon S3 object containing the environment variable file. type -&gt; (string) [required] The file type to use. Environment files are objects in Amazon S3. The only supported value is s3 . Possible values: o s3 environment -&gt; (list) The environment variables to pass to a container. (structure) A key-value pair object. name -&gt; (string) The name of the key-value pair. For environment vari- ables, this is the name of the environment variable. value -&gt; (string) The value of the key-value pair. For environment vari- ables, this is the value of the environment variable. secrets -&gt; (list) The secrets to pass to the container. (structure) An object representing the secret to expose to your con- tainer. Secrets can be exposed to a container in the fol- lowing ways: o To inject sensitive data into your containers as envi- ronment variables, use the secrets container definition parameter. o To reference sensitive information in the log configu- ration of a container, use the secretOptions container definition parameter. For more information, see Specifying sensitive data in the Amazon Elastic Container Service Developer Guide . name -&gt; (string) [required] The name of the secret. valueFrom -&gt; (string) [required] The secret to expose to the container. The supported values are either the full ARN of the Secrets Manager secret or the full ARN of the parameter in the SSM Pa- rameter Store. For information about the require Identity and Access Management permissions, see Required IAM permissions for Amazon ECS secrets (for Secrets Manager) or Required IAM permissions for Amazon ECS secrets (for Systems Manager Parameter store) in the Amazon Elastic Container Service Developer Guide . NOTE: If the SSM Parameter Store parameter exists in the same Region as the task you're launching, then you can use either the full ARN or name of the parame- ter. If the parameter exists in a different Re- gion, then the full ARN must be specified. readonlyRootFilesystem -&gt; (boolean) When this parameter is true, the container is given read-only access to its root file system. mountPoints -&gt; (list) The mount points for data volumes in your container. (structure) The details for a volume mount point that's used in a container definition. sourceVolume -&gt; (string) The name of the volume to mount. Must be a volume name referenced in the name parameter of task definition volume . containerPath -&gt; (string) The path on the container to mount the host volume at. readOnly -&gt; (boolean) If this value is true , the container has read-only access to the volume. If this value is false , then the container can write to the volume. The default value is false . logConfiguration -&gt; (structure) The log configuration specification for the container. logDriver -&gt; (string) [required] The log driver to use for the container. For tasks on Fargate, the supported log drivers are awslogs , splunk , and awsfirelens . For tasks hosted on Amazon EC2 instances, the supported log drivers are awslogs , fluentd , gelf , json-file , journald , syslog , splunk , and awsfirelens . For more information about using the awslogs log driver, see Send Amazon ECS logs to CloudWatch in the Amazon Elastic Container Service Developer Guide . For more information about using the awsfirelens log dri- ver, see Send Amazon ECS logs to an Amazon Web Services service or Amazon Web Services Partner . NOTE: If you have a custom driver that isn't listed, you can fork the Amazon ECS container agent project that's available on GitHub and customize it to work with that driver. We encourage you to submit pull requests for changes that you would like to have included. However, we don't currently provide support for running modi- fied copies of this software. Possible values: o json-file o syslog o journald o gelf o fluentd o awslogs o splunk o awsfirelens options -&gt; (map) The configuration options to send to the log driver. The options you can specify depend on the log driver. Some of the options you can specify when you use the awslogs log driver to route logs to Amazon CloudWatch in- clude the following: awslogs-create-group Required: No Specify whether you want the log group to be created au- tomatically. If this option isn't specified, it defaults to false . NOTE: Your IAM policy must include the logs:CreateLogGroup permission before you attempt to use awslogs-cre- ate-group . awslogs-region Required: Yes Specify the Amazon Web Services Region that the awslogs log driver is to send your Docker logs to. You can choose to send all of your logs from clusters in different Re- gions to a single region in CloudWatch Logs. This is so that they're all visible in one location. Otherwise, you can separate them by Region for more granularity. Make sure that the specified log group exists in the Region that you specify with this option. awslogs-group Required: Yes Make sure to specify a log group that the awslogs log driver sends its log streams to. awslogs-stream-prefix Required: Yes, when using Fargate.Optional when using EC2. Use the awslogs-stream-prefix option to associate a log stream with the specified prefix, the container name, and the ID of the Amazon ECS task that the container belongs to. If you specify a prefix with this option, then the log stream takes the format prefix-name/con- tainer-name/ecs-task-id . If you don't specify a prefix with this option, then the log stream is named after the container ID that's as- signed by the Docker daemon on the container instance. Because it's difficult to trace logs back to the con- tainer that sent them with just the Docker container ID (which is only available on the container instance), we recommend that you specify a prefix with this option. For Amazon ECS services, you can use the service name as the prefix. Doing so, you can trace log streams to the service that the container belongs to, the name of the container that sent them, and the ID of the task that the container belongs to. You must specify a stream-prefix for your logs to have your logs appear in the Log pane when using the Amazon ECS console. awslogs-datetime-format Required: No This option defines a multiline start pattern in Python strftime format. A log message consists of a line that matches the pattern and any following lines that dont match the pattern. The matched line is the delimiter be- tween log messages. One example of a use case for using this format is for parsing output such as a stack dump, which might other- wise be logged in multiple entries. The correct pattern allows it to be captured in a single entry. For more information, see awslogs-datetime-format . You cannot configure both the awslogs-datetime-format and awslogs-multiline-pattern options. NOTE: Multiline logging performs regular expression parsing and matching of all log messages. This might have a negative impact on logging performance. awslogs-multiline-pattern Required: No This option defines a multiline start pattern that uses a regular expression. A log message consists of a line that matches the pattern and any following lines that dont match the pattern. The matched line is the delimiter be- tween log messages. For more information, see awslogs-multiline-pattern . This option is ignored if awslogs-datetime-format is also configured. You cannot configure both the awslogs-datetime-format and awslogs-multiline-pattern options. NOTE: Multiline logging performs regular expression parsing and matching of all log messages. This might have a negative impact on logging performance. The following options apply to all supported log drivers. mode Required: No Valid values: non-blocking | blocking This option defines the delivery mode of log messages from the container to the log driver specified using log- Driver . The delivery mode you choose affects application availability when the flow of logs from container is in- terrupted. If you use the blocking mode and the flow of logs is in- terrupted, calls from container code to write to the std- out and stderr streams will block. The logging thread of the application will block as a result. This may cause the application to become unresponsive and lead to con- tainer healthcheck failure. If you use the non-blocking mode, the container's logs are instead stored in an in-memory intermediate buffer configured with the max-buffer-size option. This prevents the application from becoming unresponsive when logs can- not be sent. We recommend using this mode if you want to ensure service availability and are okay with some log loss. For more information, see Preventing log loss with non-blocking mode in the ``awslogs` container log driver &lt;- http://aws.amazon.com/blogs/containers/prevent- ing-log-loss-with-non-blocking-mode-in-the-awslogs-con- tainer-log-driver/&gt;`__ . You can set a default mode for all containers in a spe- cific Amazon Web Services Region by using the defaultLog- DriverMode account setting. If you don't specify the mode option or configure the account setting, Amazon ECS will default to the non-blocking mode. For more information about the account setting, see Default log driver mode in the Amazon Elastic Container Service Developer Guide . NOTE: On June 25, 2025, Amazon ECS changed the default log driver mode from blocking to non-blocking to priori- tize task availability over logging. To continue using the blocking mode after this change, do one of the following: o Set the mode option in your container definition's logConfiguration as blocking . o Set the defaultLogDriverMode account setting to blocking . max-buffer-size Required: No Default value: 10m When non-blocking mode is used, the max-buffer-size log option controls the size of the buffer that's used for intermediate message storage. Make sure to specify an ad- equate buffer size based on your application. When the buffer fills up, further logs cannot be stored. Logs that cannot be stored are lost. To route logs using the splunk log router, you need to specify a splunk-token and a splunk-url . When you use the awsfirelens log router to route logs to an Amazon Web Services Service or Amazon Web Services Partner Network destination for log storage and analyt- ics, you can set the log-driver-buffer-limit option to limit the number of events that are buffered in memory, before being sent to the log router container. It can help to resolve potential log loss issue because high throughput might result in memory running out for the buffer inside of Docker. Other options you can specify when using awsfirelens to route logs depend on the destination. When you export logs to Amazon Data Firehose, you can specify the Amazon Web Services Region with region and a name for the log stream with delivery_stream . When you export logs to Amazon Kinesis Data Streams, you can specify an Amazon Web Services Region with region and a data stream name with stream . When you export logs to Amazon OpenSearch Service, you can specify options like Name , Host (OpenSearch Service endpoint without protocol), Port , Index , Type , Aws_auth , Aws_region , Suppress_Type_Name , and tls . For more information, see Under the hood: FireLens for Amazon ECS Tasks . When you export logs to Amazon S3, you can specify the bucket using the bucket option. You can also specify re- gion , total_file_size , upload_timeout , and use_put_ob- ject as options. This parameter requires version 1.19 of the Docker Remote API or greater on your container instance. To check the Docker Remote API version on your container instance, log in to your container instance and run the following com- mand: sudo docker version --format '{{.Server.APIVer- sion}}' key -&gt; (string) value -&gt; (string) secretOptions -&gt; (list) The secrets to pass to the log configuration. For more information, see Specifying sensitive data in the Amazon Elastic Container Service Developer Guide . (structure) An object representing the secret to expose to your container. Secrets can be exposed to a container in the following ways: o To inject sensitive data into your containers as en- vironment variables, use the secrets container defi- nition parameter. o To reference sensitive information in the log con- figuration of a container, use the secretOptions container definition parameter. For more information, see Specifying sensitive data in the Amazon Elastic Container Service Developer Guide . name -&gt; (string) [required] The name of the secret. valueFrom -&gt; (string) [required] The secret to expose to the container. The sup- ported values are either the full ARN of the Se- crets Manager secret or the full ARN of the para- meter in the SSM Parameter Store. For information about the require Identity and Ac- cess Management permissions, see Required IAM per- missions for Amazon ECS secrets (for Secrets Man- ager) or Required IAM permissions for Amazon ECS secrets (for Systems Manager Parameter store) in the Amazon Elastic Container Service Developer Guide . NOTE: If the SSM Parameter Store parameter exists in the same Region as the task you're launching, then you can use either the full ARN or name of the parameter. If the parameter exists in a different Region, then the full ARN must be specified. firelensConfiguration -&gt; (structure) The FireLens configuration for the container. This is used to specify and configure a log router for container logs. type -&gt; (string) [required] The log router to use. The valid values are fluentd or fluentbit . Possible values: o fluentd o fluentbit options -&gt; (map) The options to use when configuring the log router. This field is optional and can be used to specify a custom configuration file or to add additional metadata, such as the task, task definition, cluster, and container in- stance details to the log event. If specified, the syntax to use is "options":{"enable-ecs-log-meta- data":"true|false","config-file-type:"s3|file","con- fig-file-value":"arn:aws:s3:::mybucket/flu- ent.conf|filepath"} . For more information, see Creating a task definition that uses a FireLens configuration in the Amazon Elastic Container Service Developer Guide . NOTE: Tasks hosted on Fargate only support the file configu- ration file type. key -&gt; (string) value -&gt; (string) privileged -&gt; (boolean) When this parameter is true, the container is given elevated privileges on the host container instance (similar to the root user). user -&gt; (string) The user to use inside the container. ulimits -&gt; (list) A list of ulimits to set in the container. (structure) The ulimit settings to pass to the container. Amazon ECS tasks hosted on Fargate use the default re- source limit values set by the operating system with the exception of the nofile resource limit parameter which Fargate overrides. The nofile resource limit sets a re- striction on the number of open files that a container can use. The default nofile soft limit is 65535 and the default hard limit is 65535 . You can specify the ulimit settings for a container in a task definition. name -&gt; (string) [required] The type of the ulimit . Possible values: o core o cpu o data o fsize o locks o memlock o msgqueue o nice o nofile o nproc o rss o rtprio o rttime o sigpending o stack softLimit -&gt; (integer) [required] The soft limit for the ulimit type. The value can be specified in bytes, seconds, or as a count, depending on the type of the ulimit . hardLimit -&gt; (integer) [required] The hard limit for the ulimit type. The value can be specified in bytes, seconds, or as a count, depending on the type of the ulimit . linuxParameters -&gt; (structure) Linux-specific modifications that are applied to the con- tainer configuration, such as Linux kernel capabilities. capabilities -&gt; (structure) The Linux capabilities for the container that are added to or dropped from the default configuration provided by Docker. add -&gt; (list) The Linux capabilities for the container that have been added to the default configuration provided by Docker. This parameter maps to CapAdd in the docker container create command and the --cap-add option to docker run. NOTE: Tasks launched on Fargate only support adding the SYS_PTRACE kernel capability. Valid values: "ALL" | "AUDIT_CONTROL" | "AUDIT_WRITE" | "BLOCK_SUSPEND" | "CHOWN" | "DAC_OVERRIDE" | "DAC_READ_SEARCH" | "FOWNER" | "FSETID" | "IPC_LOCK" | "IPC_OWNER" | "KILL" | "LEASE" | "LINUX_IMMUTABLE" | "MAC_ADMIN" | "MAC_OVERRIDE" | "MKNOD" | "NET_ADMIN" | "NET_BIND_SERVICE" | "NET_BROADCAST" | "NET_RAW" | "SETFCAP" | "SETGID" | "SETPCAP" | "SETUID" | "SYS_AD- MIN" | "SYS_BOOT" | "SYS_CHROOT" | "SYS_MODULE" | "SYS_NICE" | "SYS_PACCT" | "SYS_PTRACE" | "SYS_RAWIO" | "SYS_RESOURCE" | "SYS_TIME" | "SYS_TTY_CONFIG" | "SYSLOG" | "WAKE_ALARM" (string) drop -&gt; (list) The Linux capabilities for the container that have been removed from the default configuration provided by Docker. This parameter maps to CapDrop in the docker container create command and the --cap-drop op- tion to docker run. Valid values: "ALL" | "AUDIT_CONTROL" | "AUDIT_WRITE" | "BLOCK_SUSPEND" | "CHOWN" | "DAC_OVERRIDE" | "DAC_READ_SEARCH" | "FOWNER" | "FSETID" | "IPC_LOCK" | "IPC_OWNER" | "KILL" | "LEASE" | "LINUX_IMMUTABLE" | "MAC_ADMIN" | "MAC_OVERRIDE" | "MKNOD" | "NET_ADMIN" | "NET_BIND_SERVICE" | "NET_BROADCAST" | "NET_RAW" | "SETFCAP" | "SETGID" | "SETPCAP" | "SETUID" | "SYS_AD- MIN" | "SYS_BOOT" | "SYS_CHROOT" | "SYS_MODULE" | "SYS_NICE" | "SYS_PACCT" | "SYS_PTRACE" | "SYS_RAWIO" | "SYS_RESOURCE" | "SYS_TIME" | "SYS_TTY_CONFIG" | "SYSLOG" | "WAKE_ALARM" (string) devices -&gt; (list) Any host devices to expose to the container. (structure) An object representing a container instance host de- vice. hostPath -&gt; (string) [required] The path for the device on the host container in- stance. containerPath -&gt; (string) The path inside the container at which to expose the host device. permissions -&gt; (list) The explicit permissions to provide to the con- tainer for the device. By default, the container has permissions for read , write , and mknod for the device. (string) Possible values: o read o write o mknod initProcessEnabled -&gt; (boolean) Run an init process inside the container that forwards signals and reaps processes. tmpfs -&gt; (list) The container path, mount options, and size (in MiB) of the tmpfs mount. (structure) The container path, mount options, and size of the tmpfs mount. containerPath -&gt; (string) [required] The absolute file path where the tmpfs volume is to be mounted. size -&gt; (integer) [required] The maximum size (in MiB) of the tmpfs volume. mountOptions -&gt; (list) The list of tmpfs volume mount options. Valid values: "defaults" | "ro" | "rw" | "suid" | "nosuid" | "dev" | "nodev" | "exec" | "noexec" | "sync" | "async" | "dirsync" | "remount" | "mand" | "nomand" | "atime" | "noatime" | "diratime" | "nodiratime" | "bind" | "rbind" | "unbindable" | "runbindable" | "private" | "rprivate" | "shared" | "rshared" | "slave" | "rslave" | "relatime" | "norelatime" | "strictatime" | "nostrictatime" | "mode" | "uid" | "gid" | "nr_inodes" | "nr_blocks" | "mpol" (string) dependsOn -&gt; (list) The dependencies defined for container startup and shutdown. A container can contain multiple dependencies on other con- tainers in a task definition. (structure) The dependencies defined for container startup and shut- down. A container can contain multiple dependencies. When a dependency is defined for container startup, for con- tainer shutdown it is reversed. Your Amazon ECS container instances require at least ver- sion 1.26.0 of the container agent to use container de- pendencies. However, we recommend using the latest con- tainer agent version. For information about checking your agent version and updating to the latest version, see Updating the Amazon ECS Container Agent in the Amazon Elastic Container Service Developer Guide . If you're us- ing an Amazon ECS-optimized Linux AMI, your instance needs at least version 1.26.0-1 of the ecs-init package. If your container instances are launched from version 20190301 or later, then they contain the required ver- sions of the container agent and ecs-init . For more in- formation, see Amazon ECS-optimized Linux AMI in the Ama- zon Elastic Container Service Developer Guide . NOTE: For tasks that use the Fargate launch type, the task or service requires the following platforms: o Linux platform version 1.3.0 or later. o Windows platform version 1.0.0 or later. For more information about how to create a container de- pendency, see Container dependency in the Amazon Elastic Container Service Developer Guide . containerName -&gt; (string) [required] The name of a container. condition -&gt; (string) [required] The dependency condition of the container. The follow- ing are the available conditions and their behavior: o START - This condition emulates the behavior of links and volumes today. It validates that a depen- dent container is started before permitting other containers to start. o COMPLETE - This condition validates that a dependent container runs to completion (exits) before permit- ting other containers to start. This can be useful for nonessential containers that run a script and then exit. This condition can't be set on an essen- tial container. o SUCCESS - This condition is the same as COMPLETE , but it also requires that the container exits with a zero status. This condition can't be set on an es- sential container. o HEALTHY - This condition validates that the depen- dent container passes its Docker health check before permitting other containers to start. This requires that the dependent container has health checks con- figured. This condition is confirmed only at task startup. Possible values: o START o COMPLETE o SUCCESS o HEALTHY startTimeout -&gt; (integer) Time duration (in seconds) to wait before giving up on re- solving dependencies for a container. stopTimeout -&gt; (integer) Time duration (in seconds) to wait before the container is forcefully killed if it doesn't exit normally on its own. systemControls -&gt; (list) A list of namespaced kernel parameters to set in the con- tainer. (structure) A list of namespaced kernel parameters to set in the con- tainer. This parameter maps to Sysctls in the docker con- tainer create command and the --sysctl option to docker run. For example, you can configure net.ipv4.tcp_keepalive_time setting to maintain longer lived connections. We don't recommend that you specify network-related sys- temControls parameters for multiple containers in a sin- gle task that also uses either the awsvpc or host network mode. Doing this has the following disadvantages: o For tasks that use the awsvpc network mode including Fargate, if you set systemControls for any container, it applies to all containers in the task. If you set different systemControls for multiple containers in a single task, the container that's started last deter- mines which systemControls take effect. o For tasks that use the host network mode, the network namespace systemControls aren't supported. If you're setting an IPC resource namespace to use for the containers in the task, the following conditions ap- ply to your system controls. For more information, see IPC mode . o For tasks that use the host IPC mode, IPC namespace systemControls aren't supported. o For tasks that use the task IPC mode, IPC namespace systemControls values apply to all containers within a task. NOTE: This parameter is not supported for Windows contain- ers. NOTE: This parameter is only supported for tasks that are hosted on Fargate if the tasks are using platform ver- sion 1.4.0 or later (Linux). This isn't supported for Windows containers on Fargate. namespace -&gt; (string) The namespaced kernel parameter to set a value for. value -&gt; (string) The namespaced kernel parameter to set a value for. Valid IPC namespace values: "kernel.msgmax" | "ker- nel.msgmnb" | "kernel.msgmni" | "kernel.sem" | "ker- nel.shmall" | "kernel.shmmax" | "kernel.shmmni" | "kernel.shm_rmid_forced" , and Sysctls that start with "fs.mqueue.*" Valid network namespace values: Sysctls that start with "net.*" . Only namespaced Sysctls that exist within the container starting with "net.* are ac- cepted. All of these values are supported by Fargate. interactive -&gt; (boolean) When this parameter is true , you can deploy containerized applications that require stdin or a tty to be allocated. pseudoTerminal -&gt; (boolean) When this parameter is true , a TTY is allocated. restartPolicy -&gt; (structure) The restart policy for the container. When you set up a restart policy, Amazon ECS can restart the container without needing to replace the task. enabled -&gt; (boolean) [required] Specifies whether a restart policy is enabled for the container. ignoredExitCodes -&gt; (list) A list of exit codes that Amazon ECS will ignore and not attempt a restart on. You can specify a maximum of 50 container exit codes. By default, Amazon ECS does not ig- nore any exit codes. (integer) restartAttemptPeriod -&gt; (integer) A period of time (in seconds) that the container must run for before a restart can be attempted. A container can be restarted only once every restartAttemptPeriod seconds. If a container isn't able to run for this time period and exits early, it will not be restarted. You can set a min- imum restartAttemptPeriod of 60 seconds and a maximum restartAttemptPeriod of 1800 seconds. By default, a con- tainer must run for 300 seconds before it can be restarted. JSON Syntax: [ { "name": "string", "image": "string", "memory": integer, "memoryReservation": integer, "repositoryCredentials": { "credentialsParameter": "string" }, "healthCheck": { "command": ["string", ...], "interval": integer, "timeout": integer, "retries": integer, "startPeriod": integer }, "cpu": integer, "essential": true|false, "entryPoint": ["string", ...], "command": ["string", ...], "workingDirectory": "string", "environmentFiles": [ { "value": "string", "type": "s3" } ... ], "environment": [ { "name": "string", "value": "string" } ... ], "secrets": [ { "name": "string", "valueFrom": "string" } ... ], "readonlyRootFilesystem": true|false, "mountPoints": [ { "sourceVolume": "string", "containerPath": "string", "readOnly": true|false } ... ], "logConfiguration": { "logDriver": "json-file"|"syslog"|"journald"|"gelf"|"fluentd"|"awslogs"|"splunk"|"awsfirelens", "options": {"string": "string" ...}, "secretOptions": [ { "name": "string", "valueFrom": "string" } ... ] }, "firelensConfiguration": { "type": "fluentd"|"fluentbit", "options": {"string": "string" ...} }, "privileged": true|false, "user": "string", "ulimits": [ { "name": "core"|"cpu"|"data"|"fsize"|"locks"|"memlock"|"msgqueue"|"nice"|"nofile"|"nproc"|"rss"|"rtprio"|"rttime"|"sigpending"|"stack", "softLimit": integer, "hardLimit": integer } ... ], "linuxParameters": { "capabilities": { "add": ["string", ...], "drop": ["string", ...] }, "devices": [ { "hostPath": "string", "containerPath": "string", "permissions": ["read"|"write"|"mknod", ...] } ... ], "initProcessEnabled": true|false, "tmpfs": [ { "containerPath": "string", "size": integer, "mountOptions": ["string", ...] } ... ] }, "dependsOn": [ { "containerName": "string", "condition": "START"|"COMPLETE"|"SUCCESS"|"HEALTHY" } ... ], "startTimeout": integer, "stopTimeout": integer, "systemControls": [ { "namespace": "string", "value": "string" } ... ], "interactive": true|false, "pseudoTerminal": true|false, "restartPolicy": { "enabled": true|false, "ignoredExitCodes": [integer, ...], "restartAttemptPeriod": integer } } ... ]
    /// </summary>
    [CliOption("--container-definitions", GroupValues = true)]
    public IEnumerable<string>? ContainerDefinitions { get; private init; }

    /// <summary>
    /// The short name or full Amazon Resource Name (ARN) of the IAM role that containers in this daemon task can assume. All containers in this daemon task are granted the permissions that are specified in this role.
    /// </summary>
    [CliOption("--task-role-arn")]
    public string? TaskRoleArn { get; set; }

    /// <summary>
    /// The Amazon Resource Name (ARN) of the task execution role that grants the Amazon ECS container agent permission to make Amazon Web Services API calls on your behalf. The task execution role is re- quired for daemon tasks that pull container images from Amazon ECR or send container logs to CloudWatch.
    /// </summary>
    [CliOption("--execution-role-arn")]
    public string? ExecutionRoleArn { get; set; }

    /// <summary>
    /// The number of CPU units used by the daemon task. It can be expressed as an integer using CPU units (for example, 1024 ).
    /// </summary>
    [CliOption("--cpu")]
    public string? Cpu { get; set; }

    /// <summary>
    /// The amount of memory (in MiB) used by the daemon task. It can be ex- pressed as an integer using MiB (for example, 1024 ).
    /// </summary>
    [CliOption("--memory")]
    public string? Memory { get; set; }

    /// <summary>
    /// A list of volume definitions in JSON format that containers in your daemon task can use. (structure) A data volume definition for a daemon task. name -&gt; (string) The name of the volume. Up to 255 letters (uppercase and low- ercase), numbers, underscores, and hyphens are allowed. host -&gt; (structure) The contents of the host parameter determine whether your bind mount host volume persists on the host container in- stance and where it's stored. sourcePath -&gt; (string) When the host parameter is used, specify a sourcePath to declare the path on the host container instance that's presented to the container. If this parameter is empty, then the Docker daemon has assigned a host path for you. If the host parameter contains a sourcePath file loca- tion, then the data volume persists at the specified lo- cation on the host container instance until you delete it manually. If the sourcePath value doesn't exist on the host container instance, the Docker daemon creates it. If the location does exist, the contents of the source path folder are exported. If you're using the Fargate launch type, the sourcePath parameter is not supported. Shorthand Syntax: name=string,host={sourcePath=string} ... JSON Syntax: [ { "name": "string", "host": { "sourcePath": "string" } } ... ]
    /// </summary>
    [CliOption("--volumes", GroupValues = true)]
    public IEnumerable<string>? Volumes { get; set; }

    /// <summary>
    /// The metadata that you apply to the daemon task definition to help you categorize and organize them. Each tag consists of a key and an optional value. You define both of them. The following basic restrictions apply to tags: o Maximum number of tags per resource - 50 o For each resource, each tag key must be unique, and each tag key can have only one value. o Maximum key length - 128 Unicode characters in UTF-8 o Maximum value length - 256 Unicode characters in UTF-8 o If your tagging schema is used across multiple services and re- sources, remember that other services may have restrictions on al- lowed characters. Generally allowed characters are: letters, num- bers, and spaces representable in UTF-8, and the following charac- ters: + - = . _ : / @. o Tag keys and values are case-sensitive. o Do not use aws: , AWS: , or any upper or lowercase combination of such as a prefix for either keys or values as it is reserved for Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with this prefix do not count against your tags per resource limit. Constraints: o min: 0 o max: 50 (structure) The metadata that you apply to a resource to help you categorize and organize them. Each tag consists of a key and an optional value. You define them. The following basic restrictions apply to tags: o Maximum number of tags per resource - 50 o For each resource, each tag key must be unique, and each tag key can have only one value. o Maximum key length - 128 Unicode characters in UTF-8 o Maximum value length - 256 Unicode characters in UTF-8 o If your tagging schema is used across multiple services and resources, remember that other services may have restrictions on allowed characters. Generally allowed characters are: let- ters, numbers, and spaces representable in UTF-8, and the fol- lowing characters: + - = . _ : / @. o Tag keys and values are case-sensitive. o Do not use aws: , AWS: , or any upper or lowercase combination of such as a prefix for either keys or values as it is re- served for Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with this prefix do not count against your tags per resource limit. key -&gt; (string) One part of a key-value pair that make up a tag. A key is a general label that acts like a category for more specific tag values. Constraints: o min: 1 o max: 128 o pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) value -&gt; (string) The optional part of a key-value pair that make up a tag. A value acts as a descriptor within a tag category (key). Constraints: o min: 0 o max: 256 o pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) Shorthand Syntax: key=string,value=string ... JSON Syntax: [ { "key": "string", "value": "string" } ... ]
    /// </summary>
    [CliOption("--tags", GroupValues = true)]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// The PID namespace mode for the daemon. The valid values are none and shared . The default is none . If none is specified or no value is provided, the daemon runs with its own PID namespace, isolated from other tasks. If shared is spec- ified, the daemon joins the host PID namespace, making it accessible to non-daemon tasks that use pidMode: "host" or other daemons that use pidMode: "shared" . Possible values: o none o shared
    /// </summary>
    [CliOption("--pid-mode")]
    public AwsEcsRegisterDaemonTaskDefinitionPidMode? PidMode { get; set; }

    /// <summary>
    /// The IPC namespace mode for the daemon. The valid values are none and shared . The default is none . If none is specified or no value is provided, the daemon runs with its own IPC namespace, isolated from other tasks. If shared is spec- ified, the daemon joins the host IPC namespace, making it accessible to non-daemon tasks that use ipcMode: "host" or other daemons that use ipcMode: "shared" . Possible values: o none o shared
    /// </summary>
    [CliOption("--ipc-mode")]
    public AwsEcsRegisterDaemonTaskDefinitionIpcMode? IpcMode { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

